WITH gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS session_start_flag FROM payments), sessions_payments AS (SELECT id, order_id, paid_at, SUM(session_start_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT CASE WHEN burst_id >= 7 THEN 'HIGH' ELSE 'LOW' END AS burst_id_tier, DATE_TRUNC('QUARTER', paid_at) AS quarter_start, APPROX_PERCENTILE(burst_id, 0.5) AS burst_id_p50, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, PERCENTILE_APPROX(burst_id, 0.95) AS burst_id_p95, AVG(burst_id) AS avg_burst_id, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min_2, MIN(paid_at) AS started_at FROM sessions_payments GROUP BY 1, 2 HAVING avg_burst_id > 0;
